def P(s,ur,en,ps,**m): add(s,f'p{len(s["paras"])+1}',en,ur,ps,**m)
def A(s,ar,ur,en,ps):
    add(s,f'a{len(s["paras"])+1}',ar+'\n'+en,ar+'\n'+ur,ar+'\n'+ps,kind='quran')
def I(s,items,g):
    for ur,en,ps in items: add(s,f'i{len(s["paras"])+1}',en,ur,ps,listGroup=g)
