def O(s,ur,en,ps,u='l11'): add(s,f'o{len(s["paras"])+1}',en,ur,ps,role='option',exerciseId=f'mq11-{u}-q',tab='exercise')
def MC(s,q,vals):
    Q(s,*q)
    for a,e,v in zip(['الف','ب','ج','د'],['a','b','c','d'],vals):
        O(s,f'{a}) {v[0]}',f'({e}) {v[1]}',f'{a}) {v[2]}')
